WITH order_summary AS (SELECT order_id, MAX(unit_price) AS max_unit_price, ROUND(AVG(unit_price), 2) AS avg_unit_price FROM order_items GROUP BY order_id) SELECT orders.store_id, orders.order_date, order_summary.max_unit_price, order_summary.avg_unit_price FROM orders LEFT JOIN order_summary ON orders.id = order_summary.order_id WHERE order_summary.avg_unit_price > 37 ORDER BY store_id DESC;
